// HasOrders applies the HasEdge predicate on the "orders" edge.
func HasOrders() predicate.TrainOffer {
	return predicate.TrainOffer(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, true, OrdersTable, OrdersColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasOrdersWith applies the HasEdge predicate on the "orders" edge with a given conditions (other predicates).
func HasOrdersWith(preds ...predicate.TravelOrder) predicate.TrainOffer {
	return predicate.TrainOffer(func(s *sql.Selector) {
		step := newOrdersStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.TrainOffer) predicate.TrainOffer {
	return predicate.TrainOffer(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.TrainOffer) predicate.TrainOffer {
	return predicate.TrainOffer(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.TrainOffer) predicate.TrainOffer {
	return predicate.TrainOffer(sql.NotPredicates(p))
}
